visual.source:
flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
  EC2@{ svc: "Amazon EC2", label: "EC2: インスタンス" }
  ECS@{ svc: "Amazon ECS", label: "ECS: コンテナ" }
  L@{ svc: "AWS Lambda", label: "Lambda: サーバーレス" }
  CD -- "agent が要る" --> EC2
  CD -- "agent 不要" --> ECS
  CD -- "agent 不要" --> L

flowchart TB
  SSM@{ svc: "AWS Systems Manager", label: "Systems Manager" }
  EC2@{ svc: "Amazon EC2", label: "EC2 / On-Premises: agent" }
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
  X["ECS・Lambda<br/>agent は要らない"]
  SSM -- "導入" --> EC2
  EC2 -- "HTTPS 443 外向き" --> CD
  CD -- "デプロイ" --> X

flowchart TB
  IAM@{ svc: "AWS IAM", label: "IAM: instance profile" }
  EC2@{ svc: "Amazon EC2", label: "EC2: CodeDeploy agent" }
  S3@{ svc: "Amazon S3", label: "S3: 成果物・agent" }
  CA@{ svc: "AWS CodeArtifact", label: "CodeArtifact" }
  STS@{ svc: "AWS STS", label: "STS: Bearer token" }
  IAM -- "権限を与える" --> EC2
  EC2 -- "s3:Get* / List*" --> S3
  EC2 -- "token を取る" --> CA
  CA -. "両方の権限が要る" .- STS

flowchart TB
  ASG@{ svc: "Amazon EC2 Auto Scaling", label: "Auto Scaling: 起動" }
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy: 入れる版" }
  EC2@{ svc: "Amazon EC2", label: "新しい EC2" }
  ASG -- "lifecycle hook" --> CD
  CD -- "デプロイ" --> EC2
  EC2 -. "失敗で終了→再作成" .-> ASG

flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
  LB@{ svc: "Elastic Load Balancing", label: "ALB か NLB" }
  O["ECS: 元の task set"]
  R["ECS: replacement<br/>task set"]
  ECR@{ svc: "Amazon ECR", label: "ECR: image" }
  CD --> LB
  LB -. "移す前" .-> O
  LB -- "移した後" --> R
  ECR -- "タスク実行ロール" --> R
